CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,username VARCHAR(50) UNIQUE NOT NULL,password_hash VARCHAR(100) NOT NULL,name VARCHAR(100),role ENUM('admin','invigilator') NOT NULL DEFAULT 'invigilator');
CREATE TABLE IF NOT EXISTS students_master(enrollment_no VARCHAR(20) NOT NULL,name VARCHAR(200),program VARCHAR(300),section VARCHAR(200),subject_code VARCHAR(20) NOT NULL,subject_name VARCHAR(300),exam_date DATE NOT NULL,session VARCHAR(20) NOT NULL,PRIMARY KEY(enrollment_no,subject_code,exam_date,session),KEY(exam_date,session));
CREATE TABLE IF NOT EXISTS exam_seating(enrollment_no VARCHAR(20) NOT NULL,name VARCHAR(200),program VARCHAR(300),section VARCHAR(200),subject_code VARCHAR(20) NOT NULL,subject_name VARCHAR(300),exam_date DATE NOT NULL,session VARCHAR(20) NOT NULL,room_no VARCHAR(20) NOT NULL,seat_order INT DEFAULT 0,PRIMARY KEY(exam_date,session,enrollment_no,subject_code),KEY(exam_date,session,room_no));
CREATE TABLE IF NOT EXISTS attendance(exam_date DATE NOT NULL,session VARCHAR(20) NOT NULL,enrollment_no VARCHAR(20) NOT NULL,subject_code VARCHAR(20) NOT NULL,room_no VARCHAR(20) NOT NULL,status ENUM('Present','Absent','UFM') NOT NULL,marked_by INT,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(exam_date,session,enrollment_no,subject_code));
CREATE TABLE IF NOT EXISTS room_locks(exam_date DATE NOT NULL,session VARCHAR(20) NOT NULL,room_no VARCHAR(20) NOT NULL,PRIMARY KEY(exam_date,session,room_no));
